def transform(grid):
    # Color 1 objects change to the color of their matching shape in the grid.
    # Determine target by geometric shape: each 1 component pairs with same shape non-1 component.
    h, w = len(grid), len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==0 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); pts=[]
        while stack:
          x,y=stack.pop(); pts.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1),(x-1,y-1),(x-1,y+1),(x+1,y-1),(x+1,y+1)):
            if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==col:
              seen.add((nx,ny)); stack.append((nx,ny))
        comps.append((col,pts))
    def norm(pts):
      mr=min(x for x,y in pts); mc=min(y for x,y in pts)
      return frozenset((x-mr,y-mc) for x,y in pts)
    def variants(pts):
      out=set()
      for flip in (1,-1):
        for turns in range(4):
          p=[]
          for x,y in pts:
            x,y=x*flip,y
            for _ in range(turns): x,y=y,-x
            p.append((x,y))
          out.add(norm(p))
      return out
    result=[row[:] for row in grid]
    for col,pts in comps:
      if col != 1: continue
      shape=variants(pts)
      matches=[(other,op) for other,op in comps if other not in (0,1) and variants(op) & shape]
      if matches:
        target=matches[0][0]
        for x,y in pts: result[x][y]=target
    return result

